# Catechism bank — the manṣūbāt Q&A, items 46-58 (the section's end).
ITEMS = [
 {"n": 46, "q": {"tr": "«رَاشِدًا مَهْدِيًّا» neye misaldir?", "en": "What does «رَاشِدًا مَهْدِيًّا» exemplify?"},
  "a": {"tr": "Hâl olduğu hâlde âmili olan سِرْ fiilinin hazfine; aslı سِرْ رَاشِدًا مَهْدِيًّا.", "en": "A ḥāl whose governor سِرْ has been dropped: for سِرْ رَاشِدًا مَهْدِيًّا."},
  "ar": ["سِرْ رَاشِدًا مَهْدِيًّا"], "notes": ["hal", "hadhf-wa-taqdir"]},
 {"n": 47, "q": {"tr": "Temyizin tarifi nedir? Kaç kısımdır?", "en": "How is the tamyīz defined, and how many kinds has it?"},
  "a": {"tr": "Zikredilen ya da takdir edilen bir zattan yerleşmiş kapalılığı kaldıran isimdir. İki kısım: zikredilen zattan (عِشْرُونَ دِرْهَمًا) ve takdir edilen zattan (طَابَ زَيْدٌ نَفْسًا) kapalılığı kaldıran.",
        "en": "The noun that lifts the settled vagueness from an entity named or implied. Two kinds: from a named entity (عِشْرُونَ دِرْهَمًا) and from an implied one (طَابَ زَيْدٌ نَفْسًا)."},
  "ar": ["مَا يَرْفَعُ الْإِبْهَامَ الْمُسْتَقِرَّ عَنْ ذَاتٍ مَذْكُورَةٍ أَوْ مُقَدَّرَةٍ", "عِشْرُونَ دِرْهَمًا", "طَابَ زَيْدٌ نَفْسًا"], "notes": ["tamyiz", "al-tamyiz-wa-ahkamuh"]},
 {"n": 48, "q": {"tr": "Zikredilen zattan kapalılığı kaldıran birinci kısım temyiz nelerden kapalılığı kaldırır? Hükümleri nelerdir?", "en": "From what does the first kind of tamyīz lift vagueness, and what are its rulings?"},
  "a": {"tr": "1) Çoğu kere müfred miktardan: sayı (عِشْرُونَ دِرْهَمًا), tartı (رِطْلٌ زَيْتًا), ölçü (عَلَى التَّمْرَةِ مِثْلُهَا زُبْدًا). Miktar tenvin ya da tesniye nûnuyla tamamlanıyorsa izafet câizdir; şibh-i cem' nûnuyla tamamlanıyorsa izafet nâdiren câizdir. 2) Bazen miktar dışından: خَاتَمٌ حَدِيدًا — bu kısım çoğunlukla izafetle kullanılır.",
        "en": "1) Mostly from a single measure: number (عِشْرُونَ دِرْهَمًا), weight (رِطْلٌ زَيْتًا), capacity (عَلَى التَّمْرَةِ مِثْلُهَا زُبْدًا). Where the measure ends in tanwīn or the dual's nūn, annexation is allowed; where it ends in the plural-like nūn, only rarely. 2) Sometimes from what is no measure: خَاتَمٌ حَدِيدًا — this kind is mostly used in annexation."},
  "ar": ["عِشْرُونَ دِرْهَمًا", "رِطْلٌ زَيْتًا", "خَاتَمٌ حَدِيدًا"], "notes": ["tamyiz", "al-tamyiz-wa-ahkamuh", "asma-al-adad-fil-kafiya"]},
 {"n": 49, "q": {"tr": "Takdir edilen zattan kapalılığı kaldıran ikinci kısım temyiz nelerden kapalılığı kaldırır?", "en": "From what does the second kind of tamyīz lift vagueness?"},
  "a": {"tr": "Üç şeyden: cümledeki nisbetten (طَابَ زَيْدٌ نَفْسًا), şibh-i cümledeki nisbetten (زَيْدٌ طَيِّبٌ أَبًا), izafetteki nisbetten (أَعْجَبَنِي طِيبُهُ نَفْسًا).",
        "en": "From three things: the attribution in a sentence (طَابَ زَيْدٌ نَفْسًا), in a sentence-like phrase (زَيْدٌ طَيِّبٌ أَبًا), and in an annexation (أَعْجَبَنِي طِيبُهُ نَفْسًا)."},
  "ar": ["طَابَ زَيْدٌ نَفْسًا", "زَيْدٌ طَيِّبٌ أَبًا", "أَعْجَبَنِي طِيبُهُ نَفْسًا"], "notes": ["tamyiz", "al-tamyiz-wa-ahkamuh"]},
 {"n": 50, "q": {"tr": "«وَلِلَّهِ دَرُّهُ فَارِسًا» neye misaldir?", "en": "What does «وَلِلَّهِ دَرُّهُ فَارِسًا» exemplify?"},
  "a": {"tr": "Temyizin müştak bir sıfat olduğuna.", "en": "A tamyīz that is a derived adjective."},
  "ar": ["وَلِلَّهِ دَرُّهُ فَارِسًا"], "notes": ["tamyiz"]},
 {"n": 51, "q": {"tr": "Temyizin âmili üzerine takdimi câiz midir?", "en": "May the tamyīz precede its governor?"},
  "a": {"tr": "Âmili ism-i mübhem-i tâm ise câiz değildir: câmid bir isimdir, ameli zayıftır ve fiile benzerlikle amel eder; temyiz öne geçerse amel edemez. Âmili fiil olduğunda da esah mezhebe göre câiz değildir, çünkü temyiz mânâda fâildir ve fâil fiilin önüne geçmez.",
        "en": "Not when its governor is a complete vague noun: a rigid noun governs weakly and only by likeness to the verb, and cannot reach a tamyīz set before it. Nor, on the sounder view, when the governor is a verb, for the tamyīz is in meaning a doer, and the doer does not precede its verb."},
  "ar": [], "notes": ["tamyiz", "al-ism-al-mubham-al-tamm"]},
 {"n": 52, "q": {"tr": "Müstesnâ kaç kısımdır? Tarifleri ve misalleri nelerdir?", "en": "How many kinds has the exception, with their definitions and examples?"},
  "a": {"tr": "İki: muttasıl — lafzan ya da takdiren çok olandan إِلَّا ve kardeşleriyle çıkarılan (جَاءَنِي الْقَوْمُ إِلَّا زَيْدًا); munkatı' — إِلَّا'dan sonra zikredilip çıkarılmayan (جَاءَنِي الْقَوْمُ إِلَّا حِمَارًا).",
        "en": "Two: the connected — taken by إِلَّا and its sisters out of a plurality stated or implied (جَاءَنِي الْقَوْمُ إِلَّا زَيْدًا); the disconnected — named after إِلَّا without being taken out (جَاءَنِي الْقَوْمُ إِلَّا حِمَارًا)."},
  "ar": ["هُوَ الْمُخْرَجُ عَنْ مُتَعَدِّدٍ لَفْظًا أَوْ تَقْدِيرًا بِإِلَّا وَأَخَوَاتِهَا", "هُوَ الْمَذْكُورُ بَعْدَهَا غَيْرَ مُخْرَجٍ", "جَاءَنِي الْقَوْمُ إِلَّا حِمَارًا"], "notes": ["istithna", "al-mustathna-wa-nawah-wa-nasbuh"]},
 {"n": 53, "q": {"tr": "Müstesnânın nasbının vâcip olduğu yerler kaç mevzidir?", "en": "In how many places must the exception be in naṣb?"},
  "a": {"tr": "Dört: tam ve müsbet kelâmda sıfat olmayan إِلَّا'dan sonra (جَاءَنِي الْقَوْمُ إِلَّا زَيْدًا); müstesnâ müstesnâ-minhin önüne geçtiğinde (جَاءَنِي إِلَّا زَيْدًا الْقَوْمُ); munkatı' olduğunda (جَاءَنِي الْقَوْمُ إِلَّا حِمَارًا); خَلَا، عَدَا، مَا خَلَا، مَا عَدَا، لَيْسَ، لَا يَكُونُ'dan sonra (جَاءَنِي الْقَوْمُ خَلَا زَيْدًا، مَا عَدَا عَمْرًا، لَيْسَ زَيْدًا، سَيَجِيءُ أَهْلُكَ لَا يَكُونُ بِشْرًا).",
        "en": "Four: after non-adjectival إِلَّا in a full affirmative sentence (جَاءَنِي الْقَوْمُ إِلَّا زَيْدًا); when the exception precedes what it is taken from (جَاءَنِي إِلَّا زَيْدًا الْقَوْمُ); when it is disconnected (جَاءَنِي الْقَوْمُ إِلَّا حِمَارًا); and after خَلَا، عَدَا، مَا خَلَا، مَا عَدَا، لَيْسَ، لَا يَكُونُ (جَاءَنِي الْقَوْمُ خَلَا زَيْدًا، مَا عَدَا عَمْرًا، لَيْسَ زَيْدًا، سَيَجِيءُ أَهْلُكَ لَا يَكُونُ بِشْرًا)."},
  "ar": ["جَاءَنِي إِلَّا زَيْدًا الْقَوْمُ", "جَاءَنِي الْقَوْمُ خَلَا زَيْدًا", "سَيَجِيءُ أَهْلُكَ لَا يَكُونُ بِشْرًا"], "notes": ["istithna", "al-mustathna-wa-nawah-wa-nasbuh", "an-ala-al-kaf-mudh-wa-huruf-al-istithna-fil-kafiya"]},
 {"n": 54, "q": {"tr": "Müstesnânın diğer hükümleri nasıldır?", "en": "What are the exception's other rulings?"},
  "a": {"tr": "Nasbının vâcip olmasından başka i'râb bakımından üç hükmü daha vardır: müstesnâ-minh zikredilmiş gayr-i müsbet kelâmda إِلَّا'dan sonra nasb câiz, bedel muhtardır (مَا فَعَلُوهُ إِلَّا قَلِيلٌ / قَلِيلًا); gayr-i müsbet kelâmda müstesnâ-minh zikredilmemişse müstesnâ âmillere göre i'râblanır (مَا ضَرَبَنِي إِلَّا زَيْدٌ); غَيْر، سِوَى، سَوَاء ve حَاشَا'dan sonra mecrûrdur.",
        "en": "Besides the obligatory naṣb, three more: after إِلَّا in a non-affirmative sentence with the excepted-from stated, naṣb is allowed and badal preferred (مَا فَعَلُوهُ إِلَّا قَلِيلٌ / قَلِيلًا); in a non-affirmative sentence with it unstated, the exception takes the case its governors give (مَا ضَرَبَنِي إِلَّا زَيْدٌ); after غَيْر، سِوَى، سَوَاء and حَاشَا it is in jarr."},
  "ar": ["مَا فَعَلُوهُ إِلَّا قَلِيلٌ", "مَا ضَرَبَنِي إِلَّا زَيْدٌ"], "notes": ["istithna", "istithna-mufarragh", "al-mustathna-badaluhu-wa-jarruh-wa-ghayr-wa-illa"]},
 {"n": 55, "q": {"tr": "إِلَّا ne zaman sıfat olan غَيْر üzerine hamledilir? Misali nedir?", "en": "When is إِلَّا read as the adjective غَيْر, and what is the example?"},
  "a": {"tr": "Nekre kılınmış ve mahsur olmayan bir cem'den sonra geldiğinde, istisnâ mazur görüldüğü için غَيْر mânâsına hamledilir: لَوْ كَانَ فِيهِمَا آلِهَةٌ إِلَّا اللهُ لَفَسَدَتَا — burada istisnâ mânâyı bozar, bu yüzden إِلَّا sıfat olan غَيْر mânâsındadır.",
        "en": "When it follows an indefinite, unbounded plural, exception being excused there: لَوْ كَانَ فِيهِمَا آلِهَةٌ إِلَّا اللهُ لَفَسَدَتَا — an exception would corrupt the sense, so إِلَّا here means the adjective غَيْر."},
  "ar": ["لَوْ كَانَ فِيهِمَا آلِهَةٌ إِلَّا اللهُ لَفَسَدَتَا"], "notes": ["al-mustathna-badaluhu-wa-jarruh-wa-ghayr-wa-illa", "istithna"]},
 {"n": 56, "q": {"tr": "كَانَ bâbının haberinin âmili kaç şekilde hazfedilir? Misalleri nelerdir?", "en": "In how many ways is the governor of kāna's khabar dropped, and what are the examples?"},
  "a": {"tr": "İki: cevâzen — النَّاسُ مَجْزِيُّونَ بِأَعْمَالِهِمْ إِنْ خَيْرًا فَخَيْرٌ وَإِنْ شَرًّا فَشَرٌّ; burada dört vecih vardır: إِنْ خَيْرًا فَخَيْرٌ (إِنْ كَانَ عَمَلُهُ خَيْرًا فَجَزَاؤُهُ خَيْرٌ), إِنْ خَيْرًا فَخَيْرًا (… فَكَانَ جَزَاؤُهُ خَيْرًا), إِنْ خَيْرٌ فَخَيْرٌ (إِنْ كَانَ فِي عَمَلِهِ خَيْرٌ …), إِنْ خَيْرٌ فَخَيْرًا. Vücûben — أَمَّا أَنْتَ مُنْطَلِقًا انْطَلَقْتُ: aslı لِأَنْ كُنْتَ مُنْطَلِقًا; cer lâmı kıyâsen hazfedildi, كَانَ ihtisar için düştü, bitişik تَ munfasıl أَنْتَ'ye çevrildi, أَنْ'den sonra كَانَ'den ivaz مَا getirildi, nûn mîme idgam edildi, haber olduğu gibi kaldı.",
        "en": "Two: permittedly — النَّاسُ مَجْزِيُّونَ بِأَعْمَالِهِمْ إِنْ خَيْرًا فَخَيْرٌ وَإِنْ شَرًّا فَشَرٌّ, with four readings: إِنْ خَيْرًا فَخَيْرٌ (for إِنْ كَانَ عَمَلُهُ خَيْرًا فَجَزَاؤُهُ خَيْرٌ), إِنْ خَيْرًا فَخَيْرًا (… فَكَانَ جَزَاؤُهُ خَيْرًا), إِنْ خَيْرٌ فَخَيْرٌ (إِنْ كَانَ فِي عَمَلِهِ خَيْرٌ …), إِنْ خَيْرٌ فَخَيْرًا. Obligatorily — أَمَّا أَنْتَ مُنْطَلِقًا انْطَلَقْتُ, for لِأَنْ كُنْتَ مُنْطَلِقًا: the lām went by rule, كَانَ for brevity, the attached تَ became detached أَنْتَ, مَا came after أَنْ in place of كَانَ, the nūn merged into the mīm, and the khabar stayed as it was."},
  "ar": ["إِنْ خَيْرًا فَخَيْرٌ وَإِنْ شَرًّا فَشَرٌّ", "أَمَّا أَنْتَ مُنْطَلِقًا انْطَلَقْتُ"], "notes": ["kana-wa-akhawatuha", "hadhf-wa-taqdir", "al-afal-al-naqisa-fil-kafiya"]},
 {"n": 57, "q": {"tr": "Cinsi nefyeden لَا'nın isminin hükmü nedir? «لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللهِ»'ta kaç vecih vardır?", "en": "What is the ruling of the ism of the genus-denying لَا, and how many readings has «لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللهِ»?"},
  "a": {"tr": "Üç hükmü vardır: ismi muzâf ya da şibh-i muzâf nekre olup لَا'yı izlerse mansûbdur (لَا غُلَامَ رَجُلٍ); müfredse nasb alâmeti üzere mebnîdir (لَا رَجُلَ فِي الدَّارِ); ma'rife olursa ya da لَا ile ismi ayrılırsa ref' ve tekrar vâciptir (لَا زَيْدٌ فِي الدَّارِ وَلَا عَمْرٌو؛ لَا فِي الدَّارِ رَجُلٌ). لَا حَوْلَ وَلَا قُوَّةَ'de beş vecih: حَوْلَ … قُوَّةَ، حَوْلَ … قُوَّةً، حَوْلَ … قُوَّةٌ، حَوْلٌ … قُوَّةٌ، حَوْلٌ … قُوَّةَ.",
        "en": "Three: an indefinite ism that is annexed or annexation-like and follows لَا is in naṣb (لَا غُلَامَ رَجُلٍ); a single one is built on its naṣb sign (لَا رَجُلَ فِي الدَّارِ); a definite one, or one separated from لَا, must be in rafʿ with لَا repeated (لَا زَيْدٌ فِي الدَّارِ وَلَا عَمْرٌو؛ لَا فِي الدَّارِ رَجُلٌ). لَا حَوْلَ وَلَا قُوَّةَ has five readings: حَوْلَ … قُوَّةَ، حَوْلَ … قُوَّةً، حَوْلَ … قُوَّةٌ، حَوْلٌ … قُوَّةٌ، حَوْلٌ … قُوَّةَ."},
  "ar": ["لَا غُلَامَ رَجُلٍ", "لَا رَجُلَ فِي الدَّارِ", "لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللهِ"], "notes": ["la-nafiya-lil-jins", "ma-la-laysa-wa-la-al-jins"]},
 {"n": 58, "q": {"tr": "لَيْسَ'ye benzeyen مَا ve لَا'nın ameli ne zaman bâtıl olur?", "en": "When does the government of مَا and لَا that resemble لَيْسَ lapse?"},
  "a": {"tr": "مَا ile ismi arasına zâid إِنْ girdiğinde (مَا إِنْ زَيْدٌ قَائِمٌ); nefiy إِلَّا ile bozulduğunda (مَا زَيْدٌ إِلَّا قَائِمٌ); haberleri isimlerinin önüne geçtiğinde (مَا قَائِمٌ زَيْدٌ، لَا قَائِمٌ زَيْدٌ). Ayrıca لَا'nın ismi nekre olmalıdır; لَا ma'rifede amel etmez (لَا زَيْدٌ قَائِمٌ).",
        "en": "When an extra إِنْ comes between مَا and its ism (مَا إِنْ زَيْدٌ قَائِمٌ); when إِلَّا breaks the negation (مَا زَيْدٌ إِلَّا قَائِمٌ); when their khabar precedes their ism (مَا قَائِمٌ زَيْدٌ، لَا قَائِمٌ زَيْدٌ). And لَا's ism must be indefinite; it does not govern a definite (لَا زَيْدٌ قَائِمٌ)."},
  "ar": ["مَا إِنْ زَيْدٌ قَائِمٌ", "مَا زَيْدٌ إِلَّا قَائِمٌ", "مَا قَائِمٌ زَيْدٌ"], "notes": ["ma-la-mushabbaha", "ma-la-laysa-wa-la-al-jins"]},
]
